import {COLORS,CUE_COLORS,LETTERS,time,clamp} from './core.js';
export function startVisuals(a){let drawLast=0,textLast=0,persistLast=0,statusLast=0;const $=q=>document.querySelector(q),$$=q=>Array.from(document.querySelectorAll(q));
 function fit(canvas){const r=canvas.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1);if(r.width<2||r.height<2)return null;const w=Math.round(r.width*dpr),h=Math.round(r.height*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);return {c,w:r.width,h:r.height};}
 function draw(canvas,i,overview=false){const f=fit(canvas);if(!f)return;const {c,w,h}=f,t=a.getTrack(i),d=a.s.decks[i];c.clearRect(0,0,w,h);c.fillStyle='#0c141d';c.fillRect(0,0,w,h);if(!t?.peaks?.length){c.strokeStyle='#2b3c4d';c.beginPath();c.moveTo(0,h/2);c.lineTo(w,h/2);c.stroke();return;}const pos=a.position(i),start=overview?0:pos-a.zoom*.32,span=overview?t.duration:a.zoom,peaks=t.peaks,n=peaks.length,beat=60/t.bpm,first=Math.ceil((start-(t.gridOffset||0))/beat);c.lineWidth=1;const stride=overview?Math.max(1,Math.ceil(t.duration/beat/(w/6))):1;for(let b=first;b*beat+(t.gridOffset||0)<start+span;b+=stride){const tt=b*beat+(t.gridOffset||0);if(tt<0)continue;const x=(tt-start)/span*w;c.strokeStyle=b%4===0?'#44607b':'#243647';c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let x=0;x<w;x+=overview?2:3){const ta=start+x/w*span,tb=start+(x+3)/w*span;if(tb<0||ta>t.duration)continue;const begin=Math.max(0,Math.floor(ta/t.duration*n)),end=Math.min(n,Math.max(begin+1,Math.ceil(tb/t.duration*n)));let peak=0;for(let j=begin;j<end;j++)peak=Math.max(peak,peaks[j]);const amp=peak/255*(h*.47);c.fillStyle=ta<pos?COLORS[i]:COLORS[i]+'88';c.fillRect(x,h/2-amp,overview?1.5:2,Math.max(1,amp*2));}if(d.loop.enabled){const x=(d.loop.start-start)/span*w,width=(d.loop.end-d.loop.start)/span*w;c.fillStyle=COLORS[i]+'19';c.fillRect(x,0,width,h);c.strokeStyle=COLORS[i];c.strokeRect(x,.5,width,h-1);}(t.cues||[]).forEach((v,j)=>{if(v==null||v<start||v>start+span)return;const x=(v-start)/span*w;c.fillStyle=CUE_COLORS[j];c.fillRect(x,0,2,h);if(!overview){c.font='12px monospace';c.fillText(String.fromCharCode(65+j),x+3,12);}});const x=(pos-start)/span*w;c.fillStyle='#edf6ff';c.fillRect(x-.75,0,1.5,h);if(!overview){c.beginPath();c.moveTo(x-4,0);c.lineTo(x+4,0);c.lineTo(x,5);c.fill();}}
 function animate(now){requestAnimationFrame(animate);if(document.hidden||now-drawLast<32)return;drawLast=now;$$('[data-overview]').forEach(c=>{if(!c.closest('.panel').hidden)draw(c,Number(c.dataset.overview),true);});$$('[data-wave]').forEach(c=>{if(!c.parentElement.hidden&&!c.closest('.panel').hidden)draw(c,Number(c.dataset.wave));});
 if(now-textLast>95){textLast=now;a.s.decks.forEach((d,i)=>{const pos=a.position(i),t=a.getTrack(i);if($(`[data-time="${i}"]`))$(`[data-time="${i}"]`).textContent=time(pos);if($(`[data-remaining="${i}"]`))$(`[data-remaining="${i}"]`).textContent='−'+time((t?.duration||0)-pos);if($(`[data-jog-tick="${i}"]`))$(`[data-jog-tick="${i}"]`).style.transform=`rotate(${pos/1.8*360}deg)`;const bpm=t?(t.bpm*d.rate).toFixed(1):'—';if($(`[data-bpm="${i}"]`))$(`[data-bpm="${i}"]`).textContent=bpm;if($(`[data-wave-bpm="${i}"]`))$(`[data-wave-bpm="${i}"]`).textContent=bpm;for(const el of $$(`[data-jog="${i}"],[data-overview="${i}"]`))el.setAttribute('aria-valuenow',pos.toFixed(2));const meter=$(`[data-meter="${i}"]`);if(meter){const peak=a.engine.meter(a.engine.channels[i]?.meter);meter.style.height=clamp((20*Math.log10(peak||1e-5)+48)/48*100,0,100)+'%';}});const peak=a.engine.meter(a.engine.masterMeter);if($('[data-master-meter]'))$('[data-master-meter]').style.width=clamp((20*Math.log10(peak||1e-5)+48)/48*100,0,100)+'%';if($('[data-master-peak]')){$('[data-master-peak]').textContent=peak<.0001?'−∞ dB':(20*Math.log10(peak)).toFixed(1)+' dB';$('[data-master-peak]').classList.toggle('danger',peak>.97);}$$('[data-sample]').forEach(el=>el.classList.toggle('playing',a.engine.sampleSlots.includes(Number(el.dataset.sample))));$('#record-button').innerHTML=a.engine.recording?`<span class="record-dot"></span> REC ${time((Date.now()-a.engine.recordStarted)/1000)}`:'<span class="record-dot"></span> REC';}
 if(now-statusLast>1000){statusLast=now;const lat=a.engine.latency;if(lat)$('#latency-status').textContent=`出力 ${lat.output==null?'—':lat.output.toFixed(1)+' ms'} · 基底 ${lat.base.toFixed(1)} ms`;const hidden=a.s.decks.map((d,i)=>d.playing&&!a.s.layout[`deck${i}`].visible?LETTERS[i]:null).filter(Boolean);$('#active-status').textContent=hidden.length?`非表示デッキ ${hidden.join(' / ')} 再生中`:'';}
 if(now-persistLast>5000&&a.s.decks.some(d=>d.playing)){persistLast=now;a.save();}}
 requestAnimationFrame(animate);
}
